PRAGMA foreign_keys = ON;
 CREATE TABLE organizations (     id TEXT PRIMARY KEY,     name TEXT NOT NULL,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
 CREATE TABLE coaches (     id TEXT PRIMARY KEY,     org_id TEXT,     name TEXT NOT NULL,     email TEXT UNIQUE NOT NULL,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     FOREIGN KEY (org_id) REFERENCES organizations(id) ON DELETE SET NULL );
 CREATE TABLE users (     id TEXT PRIMARY KEY,     name TEXT NOT NULL,     email TEXT UNIQUE NOT NULL,     gender TEXT CHECK(gender IN ('male', 'female')),     height_cm REAL,     wrist_cm REAL,     shoulder_cm REAL,     ankle_cm REAL,     target_weight_kg REAL,     created_at DATETIME DEFAULT CURRENT_TIMESTAMP );
 CREATE TABLE client_measurements (     id INTEGER PRIMARY KEY AUTOINCREMENT,     user_id TEXT NOT NULL,     recorded_at DATETIME DEFAULT CURRENT_TIMESTAMP,     weight_kg REAL,     waist_cm REAL,     hips_cm REAL,     chest_cm REAL,     arm_girth_cm REAL,     thigh_girth_cm REAL,     fat_percentage REAL,     FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE );
 CREATE TABLE branding_configs (     id TEXT PRIMARY KEY,     owner_id TEXT NOT NULL, -- UUID of Coach or Organization     company_name TEXT,     logo_url TEXT,     primary_color TEXT, -- Hex code     secondary_color TEXT, -- Hex code     custom_font TEXT,     welcome_message TEXT,     custom_domain TEXT UNIQUE );
 CREATE TABLE coach_client_relations (     id TEXT PRIMARY KEY,     coach_id TEXT NOT NULL,     client_id TEXT NOT NULL,     status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending', 'active', 'terminated')),     permissions INTEGER NOT NULL DEFAULT 0, -- Bitmask: 1=Basic, 2=Meas, 4=3D, 8=Goals, 16=Checkins     created_at DATETIME DEFAULT CURRENT_TIMESTAMP,     FOREIGN KEY (coach_id) REFERENCES coaches(id) ON DELETE CASCADE,     FOREIGN KEY (client_id) REFERENCES users(id) ON DELETE CASCADE,     UNIQUE(coach_id, client_id) );
 